    pub fn pron_short_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(36);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(3, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The short pron. The best candidate; the word itself if nothing is known.
